describe("Determinism", () => {
  // TODO(I): switch to collectOffline. Lane A's src/collector/index.ts
  // `collectOffline(dir)` is still a throwing NOT_IMPLEMENTED stub as of this
  // writing (parallel lane). This is a tiny local normaliser built directly
  // from the recorded fixture at tests/fixtures/bluetokaicoffee.com/products.page1.json
  // — it maps raw Shopify product JSON onto the `Product`/`Variant` shape
  // (parsed prices, stripped body_html length, hasOwnImage from featured_image)
  // but does NOT attempt collection-membership cross-referencing, robots.txt
  // handling, or PDP sampling the way the real collector does; `collections`
  // is left empty and `policies` is hardcoded to the known robots.txt-disallowed
  // state for this store. Once Lane A's collectOffline lands, replace
  // `buildFixtureSnapshot()` below with
  // `await collectOffline("tests/fixtures/bluetokaicoffee.com")`.
  function stripHtml(html: string): string {
    return html.replace(/<[^>]*>/g, "").trim();
  }

  function normaliseFixtureProduct(raw: any): Product {
    const variants: Variant[] = raw.variants.map(
      (v: any): Variant => ({
        id: v.id,
        title: v.title,
        option1: v.option1 ?? null,
        option2: v.option2 ?? null,
        option3: v.option3 ?? null,
        price: Number(v.price),
        compareAtPrice: v.compare_at_price == null ? null : Number(v.compare_at_price),
        available: Boolean(v.available),
        hasOwnImage: v.featured_image != null,
      }),
    );
    return {
      id: raw.id,
      handle: raw.handle,
      title: raw.title,
      url: `https://bluetokaicoffee.com/products/${raw.handle}`,
      tags: raw.tags ?? [],
      options: (raw.options ?? []).map((o: any) => ({ name: o.name, position: o.position, values: o.values })),
      variants,
      imageCount: (raw.images ?? []).length,
      descriptionChars: stripHtml(raw.body_html ?? "").length,
      updatedAt: raw.updated_at,
      publishedAt: raw.published_at ?? null,
      collections: [], // see TODO(I) above
    };
  }

  function buildFixtureSnapshot(): StoreSnapshot {
    const raw = JSON.parse(
      readFileSync(new URL("./fixtures/bluetokaicoffee.com/products.page1.json", import.meta.url), "utf-8"),
    );
    const products: Product[] = raw.products.map(normaliseFixtureProduct);
    return {
      schemaVersion: 1,
      store: { host: "bluetokaicoffee.com", name: "Blue Tokai Coffee Roasters", currency: "INR" },
      fetchedAt: "2026-09-22T11:55:00.000Z",
      products,
      collections: [],
      // This store's robots.txt disallows /policies/* — see docs/decisions-during-build.md D-02.
      policies: { shipping: null, refund: null, linkedFromHome: true },
      stats: { requests: 0, cacheHits: 0, durationMs: 0 },
    };
  }

  it("is schema-valid and produces byte-identical findings (excluding generatedAt) on repeated runs", () => {
    const snapshot = buildFixtureSnapshot();
    expect(() => StoreSnapshot.parse(snapshot)).not.toThrow();
    expect(snapshot.products.length).toBe(190); // real recorded fixture, sanity check

    const markers = makeMarkers();

    const first = analyse(snapshot, markers) as any;
    const second = analyse(snapshot, markers) as any;

    delete first.generatedAt;
    delete second.generatedAt;

    expect(first).toEqual(second);
  });
});
